from taf.sbts.oam.coam.admin.interfaces.SBTS21B import (BtsStatusInterface21B,
                                                        DiagnosticInterface21B,
                                                        ProceduresInterface21B,
                                                        ParameterEditorInterface21B,
                                                        PMInterface21B,
                                                        SoftwareMgmtInterface21B,
                                                        AlarmMgmtInterface21B,
                                                        ConfigurationInterface21B,
                                                        CommonInterface21B,
                                                        AccountMgmtInterface21B,
                                                        OptionsInterface21B,
                                                        RDModeInterface21B)


class ProvidedContent(object):
    detectable_hardware = (
        "basebandModules",
        "systemModules",
        "cabinets",
        "cables",
        "gnsse",
        "gnssi",
        "powerModules",
        "radioModules",
        "transportModules"
    )
    software_information = "swInfo"
    baseband_modules_information = "basebandModules"
    cells_information = "cells"
    gnsse_information = 'gnsse'
    historic_alarms = 'historicalAlarms'
    system_modules_information = "systemModules"
    radio_modules_information = "radioModules"
    rmod_information = 'rmod'
    asirmod_information = 'asirmod'
    cabinets_information = 'cabinets'
    fan_status_locations = {
        "RMOD": (radio_modules_information, "rmod")
    }
    request_message = 'requestMessage'
    output_file_content = 'outputFileContent'


class SBTS21B(BtsStatusInterface21B,
              DiagnosticInterface21B,
              ProceduresInterface21B,
              ParameterEditorInterface21B,
              PMInterface21B,
              SoftwareMgmtInterface21B,
              AlarmMgmtInterface21B,
              ConfigurationInterface21B,
              CommonInterface21B,
              AccountMgmtInterface21B,
              OptionsInterface21B,
              RDModeInterface21B):
    """
    Class for release specific admin interface
    """
    _api_client = None
    _provided_content = ProvidedContent()

    def __init__(self,
                 api_client=None
                 ):
        """
        :param api_client: instance of an AdminApi class
        """
        self._api_client = api_client
        self._allowed_alarm_validators = []

    def __del__(self):
        self.disconnect()

    def disconnect(self):
        """
        Disconnect api client.
        """
        if self._api_client is not None:
            self._api_client.teardown()
            self._api_client = None

    def api_reset(self):
        """
        Disconnect api client.
        """
        if self._api_client is not None:
            self._api_client.reset()
